result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (LOWER(status) == "active")
).PARTITION(
    name="countries", 
    by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

active_customers_since_2023 = Customers.WHERE(
    (join_date >= "2023-01-01") & (LOWER(status) == "active")
)
country_tac = active_customers_since_2023.PARTITION(
    name="country_groups", by=country
).CALCULATE(country=country, TAC=COUNT(Customers))

result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (LOWER(status) == "active")
).PARTITION(
    name="countries", 
    by=(country,)
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

active_customers_since_2023 = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= "2023-01-01")
)
tac_by_country = active_customers_since_2023.PARTITION(
    name="country_groups", by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

