date_info = Dealership.CALCULATE(
    start_date_inclusive=DATETIME('now', 'start of month', '-6 months'),
    end_date_exclusive=DATETIME('now', 'start of month')
)

sales_in_window = date_info.Sales.CALCULATE(
    sale_month=DATETIME(sale_date, 'start of month')
).WHERE(
    (sale_month >= start_date_inclusive) & (sale_month < end_date_exclusive)
)

monthly_groups = sales_in_window.PARTITION(name='monthly_sales', by=sale_month)

final_metrics = monthly_groups.CALCULATE(
    month=sale_month,
    PMSPS=COUNT(
        Sales.WHERE(
            (YEAR(salesperson.hire_date) >= 2022) & (YEAR(salesperson.hire_date) <= 2023)
        )
    ),
    PMSR=SUM(
        Sales.WHERE(
            (YEAR(salesperson.hire_date) >= 2022) & (YEAR(salesperson.hire_date) <= 2023)
        ).sale_price
    )
)

result = final_metrics.ORDER_BY(month.ASC())

