alice_treatment_count = DermTreatment.CALCULATE(
    # Define the start of the current month
    start_of_current_month=DATETIME('now', 'start of month'),
    # Define the start of the 6-month period (6 months before the start of the current month)
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).CALCULATE(
    # Count the treatments for the patient named 'Alice' within the specified date range
    num_treatments=COUNT(
        Patients.WHERE(LOWER(first_name) == 'alice').treatments_received.WHERE(
            (start_dt >= start_of_period) & (start_dt < start_of_current_month)
        )
    )
)

