code:
result = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

top_merchants = Ewallet.Merchants.CALCULATE(
    merchant_name=name,
    total_transaction_amount=SUM(transactions_received.WHERE((receiver_type == 1) & (DATEDIFF("days", created_at, DATETIME('now')) <= 150)).amount),
    total_number_of_transactions=COUNT(transactions_received.WHERE((receiver_type == 1) & (DATEDIFF("days", created_at, DATETIME('now')) <= 150)))
).WHERE(
    total_transaction_amount > 0
).TOP_K(
    2,
    by=total_transaction_amount.DESC()
)

